import sys
from collections import deque, defaultdict

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def build_tree(nodes):
    if not nodes:
        return None
    root = Node(nodes[0])
    queue = deque([root])
    idx = 1
    while queue and idx < len(nodes):
        current = queue.popleft()
        if idx < len(nodes) and nodes[idx] is not None:
            current.left = Node(nodes[idx])
            queue.append(current.left)
        idx += 1
        if idx < len(nodes) and nodes[idx] is not None):
            current.right = Node(nodes[idx])
            queue.append(current.right)
        idx += 1
    return root

def find_target(root, target):
    if not root:
        return None
    if root.data == target:
        return root
    left = find_target(root.left, target)
    if left:
        return left
    return find_target(root.right, target)

def get_parents(root, parents):
    if not root:
        return
    if root.left:
        parents[root.left] = root
    if root.right:
        parents[root.right] = root
    get_parents(root.left, parents)
    get_parents(root.right, parents)

def k_distance_nodes(root, target, k):
    if not root:
        return []

    parents = {}
    get_parents(root, parents)

    target_node = find_target(root, target)
    if not target_node:
        return []

    visited = set()
    queue = deque([(target_node, 0)])
    visited.add(target_node)
    result = []

    while queue:
        node, dist = queue.popleft()
        if dist == k:
            result.append(node.data)
            continue
        if dist > k:
            break

        for neighbor in [node.left, node.right, parents.get(node)]:
            if neighbor and neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + 1))

    return sorted(result)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    tree_data = []
    idx = 1
    for _ in range(n):
        val = input_data[idx]
        tree_data.append(int(val) if val != 'None' else None)
        idx += 1

    target = int(input_data[idx])
    k = int(input_data[idx + 1])

    root = build_tree(tree_data)
    result = k_distance_nodes(root, target, k)

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
